1	/**
2	 * @module core/agent/ledger
3	 *
4	 * Records every tool result produced while answering one question. The answer
5	 * validator uses it as the ground truth: hubs, numbers, confidences and
6	 * caveats in the final answer must trace back to entries here.
7	 */
8	import type { ModelMessage } from "ai";
9	import { HAZARD_WEIGHTS, OVERALL_MIX, RISK_LEVEL_CUTOFFS, SCORING_WINDOW_DAYS, HALF_BLEND } from "../scoring/config";
10	import { DAY_METRICS } from "../scoring/dayMetrics";
11	import type { Confidence } from "../scoring/types";
12	import type { ToolCallRecord } from "./answerSchema";
13	
14	/** Fields every tool output carries so the ledger can read them uniformly. */
15	export interface ToolOutputBase {
16	  /** Hub ids this result contains data for. */
17	  hubIds: string[];
18	  /** Weakest confidence of the data in this result (null when not applicable, e.g. an error). */
19	  confidence: Confidence | null;
20	  /** Standing caveats that apply to this result (G4). */
21	  caveats: string[];
22	}
23	
24	/**
25	 * Numbers inside text, e.g. "72.4", "-18", "1,826". A minus sign only counts
26	 * when it is NOT right after a digit — in "0-100" the dash is a range, not a sign.
27	 */
28	const NUMBER_IN_TEXT = /(?:(?<![\d.])-)?\d[\d,]*(?:\.\d+)?/g;
29	
30	
31	/**
32	 * Collects every number in a value: numeric fields and numbers written inside strings.
33	 * @param value - any JSON-like value.
34	 * @param into - accumulator.
35	 * @returns the accumulator.
36	 */
37	export function collectNumbers(value: unknown, into: number[] = []): number[] {
38	  if (typeof value === "number" && Number.isFinite(value)) into.push(value);
39	  else if (typeof value === "string") {
40	    for (const match of value.match(NUMBER_IN_TEXT) ?? []) into.push(Number(match.replace(/,/g, "")));
41	  } else if (Array.isArray(value)) value.forEach((item) => collectNumbers(item, into));
42	  else if (value && typeof value === "object") Object.values(value).forEach((item) => collectNumbers(item, into));
43	  return into;
44	}
45	
46	/**
47	 * Fixed facts of the METHOD that answers may always quote (they come from the
48	 * system prompt, not from a tool) — all derived from config, never retyped:
49	 * the 0–100 scale, level cut-offs, formula weights, hazard weights, the 50/50
50	 * blend, the scoring window, and every hazard-day threshold in both unit systems.
51	 */
52	export const ALWAYS_KNOWN_NUMBERS: readonly number[] = [
53	  0,
54	  100,
55	  RISK_LEVEL_CUTOFFS.mediumFrom - 1,
56	  RISK_LEVEL_CUTOFFS.mediumFrom,
57	  RISK_LEVEL_CUTOFFS.highFrom - 1,
58	  RISK_LEVEL_CUTOFFS.highFrom,
59	  OVERALL_MIX.weightedAverage,
60	  OVERALL_MIX.worstHazard,
61	  OVERALL_MIX.weightedAverage * 100,
62	  OVERALL_MIX.worstHazard * 100,
63	  ...Object.values(HAZARD_WEIGHTS).flatMap((w) => [w, w * 100]),
64	  HALF_BLEND.observed * 100,
65	  HALF_BLEND.fema * 100,
66	  SCORING_WINDOW_DAYS,
67	  Math.round(SCORING_WINDOW_DAYS / 365.25),
68	  ...collectNumbers(Object.values(DAY_METRICS).map((m) => m.threshold)),
69	];
70	
71	/**
72	 * True when `claimed` matches a tool number, allowing display rounding
73	 * (72.43 may be quoted as 72.4 or 72).
74	 * @param claimed - number the answer uses.
75	 * @param known - numbers from tool results.
76	 * @returns whether it traces back to a tool.
77	 */
78	export function matchesKnownNumber(claimed: number, known: readonly number[]): boolean {
79	  return known.some(
80	    (n) => Math.abs(n - claimed) <= 0.051 || Math.round(n) === claimed || Math.abs(Math.round(n * 10) / 10 - claimed) < 1e-9,
81	  );
82	}
83	
84	/** True when a value has the fields every tool output carries. */
85	function isToolOutput(value: unknown): value is ToolOutputBase {
86	  const v = value as Partial<ToolOutputBase> | null;
87	  return !!v && typeof v === "object" && Array.isArray(v.hubIds) && Array.isArray(v.caveats) && "confidence" in v;
88	}
89	
90	/**
91	 * Extracts our tool outputs from earlier conversation turns (role "tool" messages).
92	 * @param messages - conversation history.
93	 * @returns the tool outputs found, oldest first.
94	 */
95	export function toolOutputsFromHistory(messages: readonly ModelMessage[]): ToolOutputBase[] {
96	  const outputs: ToolOutputBase[] = [];
97	  for (const message of messages) {
98	    if (message.role !== "tool" || !Array.isArray(message.content)) continue;
99	    for (const part of message.content) {
100	      if (part.type !== "tool-result") continue;
101	      const value = part.output.type === "json" ? part.output.value : null;
102	      if (isToolOutput(value)) outputs.push(value);
103	    }
104	  }
105	  return outputs;
106	}
107	
108	/**
109	 * Ground truth of one agent turn: this turn's tool results, plus tool results
110	 * from earlier turns of the same conversation (D25 — follow-ups may reuse them).
111	 */
112	export class ToolLedger {
113	  /** Every call of this turn, in order (becomes the answer's `meta.toolCalls`). */
114	  readonly calls: ToolCallRecord[] = [];
115	  /** This turn's tool outputs. */
116	  private readonly outputs: ToolOutputBase[] = [];
117	  /** Tool outputs from earlier turns of the conversation (D65). */
118	  private historyOutputs: ToolOutputBase[] = [];
119	  /** Numbers the system prompt states (hub count, this year and last year, D122). */
120	  private extraKnown: number[] = [];
121	  /** Keys of calls already started in this answer (duplicate detection, E8). */
122	  private readonly claimed = new Set<string>();
123	
124	  /**
125	   * Claims a tool call when it STARTS (so parallel duplicates in one step are caught too).
126	   * @param tool - tool name.
127	   * @param input - tool input.
128	   * @returns true the first time this exact call is seen in this answer, false for repeats.
129	   */
130	  claim(tool: string, input: unknown): boolean {
131	    const key = `${tool}:${JSON.stringify(input)}`;
132	    if (this.claimed.has(key)) return false;
133	    this.claimed.add(key);
134	    return true;
135	  }
136	
137	  /**
138	   * Adds facts known for this turn that aren't tool results (e.g. the live hub count from the prompt).
139	   * @param numbers - the numbers.
140	   */
141	  addKnownNumbers(numbers: number[]): void {
142	    this.extraKnown.push(...numbers);
143	  }
144	
145	  /**
146	   * Adds tool results from earlier turns. They count as known hubs and numbers;
147	   * their confidence and caveats are used only when this turn calls no tools.
148	   * @param messages - conversation history.
149	   */
150	  seedFromHistory(messages: readonly ModelMessage[]): void {
151	    this.historyOutputs = toolOutputsFromHistory(messages);
152	  }
153	
154	  /** Current-turn outputs if any, otherwise the earlier ones (for confidence/caveats). */
155	  private relevantOutputs(): ToolOutputBase[] {
156	    return this.outputs.length > 0 ? this.outputs : this.historyOutputs;
157	  }
158	
159	  /**
160	   * Records a tool call and its output.
161	   * @param tool - tool name.
162	   * @param input - validated tool input.
163	   * @param output - the tool's output.
164	   */
165	  record(tool: string, input: unknown, output: ToolOutputBase): void {
166	    this.calls.push({ tool, input, output });
167	    this.outputs.push(output);
168	  }
169	
170	  /** @returns every hub id any tool returned data for (this turn or earlier). */
171	  hubIds(): Set<string> {
172	    return new Set([...this.outputs, ...this.historyOutputs].flatMap((o) => o.hubIds));
173	  }
174	
175	  /** @returns every number found in tool outputs (this turn or earlier), plus the fixed scale bounds. */
176	  numbers(): number[] {
177	    return collectNumbers([...this.outputs, ...this.historyOutputs], [...ALWAYS_KNOWN_NUMBERS, ...this.extraKnown]);
178	  }
179	
180	  /** @returns the confidences of the relevant results that have one. */
181	  confidences(): Confidence[] {
182	    return this.relevantOutputs()
183	      .map((o) => o.confidence)
184	      .filter((c): c is Confidence => c !== null);
185	  }
186	
187	  /** @returns the relevant standing caveats, de-duplicated, in first-seen order. */
188	  caveats(): string[] {
189	    return [...new Set(this.relevantOutputs().flatMap((o) => o.caveats))];
190	  }
191	}
