41	                  {hub.hub}
42	                </th>
43	              ))}
44	            </tr>
45	          </thead>
46	          <tbody>
47	            {hazards.map((hazard) => (
48	              <tr key={hazard}>
49	                <th scope="row" className="whitespace-nowrap text-left text-xs font-normal text-slate-300">
50	                  <span aria-hidden="true">{HAZARD_UI[hazard].icon} </span>
51	                  {HAZARD_UI[hazard].label}
