59	                      className="rounded-md border px-2 py-1 tabular-nums"
60	                      style={{ background: ui.bg, borderColor: ui.border }}
61	                      title={`${cell.confidenceReason} (${rankText(cell.rankAmongAll, data.totalHubs)})`}
62	                    >
63	                      <span className="font-medium" style={{ color: ui.text }}>
64	                        {cell.score}
65	                      </span>{" "}
66	                      <span className="text-xs text-slate-400">{ui.label}</span>
67	                    </td>
