41	          {data.percentOfDays === null ? "—" : `${data.percentOfDays}%`}
42	        </span>
43	        <span className="text-sm text-slate-300">
44	          {data.daysMeeting} of {data.daysWithData} days with {data.threshold}
45	          <span className="text-slate-500"> · {data.hub} · {data.period.label}</span>
46	        </span>
47	      </figcaption>
48	      {/* Columns stretch to the strip's fixed height so each bar's % height has a definite parent. */}
49	      <div className={`flex gap-1 ${hasYears ? "h-28" : "h-24"}`} role="img" aria-label={describeStrip(months, what)}>
50	        {months.map((m) => (
51	          <div key={m.month} className="flex min-w-0 flex-1 flex-col items-center gap-1" title={monthTitle(m)}>
52	            <span className="text-[10px] leading-none tabular-nums text-slate-400">{m.coverage === "none" ? "–" : m.daysMeeting > 0 ? m.daysMeeting : ""}</span>
53	            <div className="relative w-full flex-1">
54	              {m.coverage === "none" ? (
55	                <div className="absolute inset-0 rounded-t-sm" style={{ background: NO_DATA_FILL }} />
56	              ) : (
57	                <div
58	                  className={`absolute inset-x-0 bottom-0 rounded-t-sm ${m.coverage === "partial" ? "bg-sky-400/35 outline-1 outline-dashed outline-sky-300/60" : "bg-sky-400/70"}`}
59	                  style={{ height: `${(m.daysMeeting / max) * 100}%`, minHeight: m.daysMeeting > 0 ? 3 : 0 }}
60	                />
61	              )}
62	            </div>
63	            <span className="whitespace-nowrap text-[10px] leading-none text-slate-500">{m.monthLabel || " "}</span>
64	            {hasYears && <span className="whitespace-nowrap text-[10px] leading-none text-slate-600">{m.yearLabel || " "}</span>}
65	          </div>
66	        ))}
67	      </div>
68	      <p className="text-[11px] text-slate-500">
69	        {what[0].toUpperCase() + what.slice(1)} per month
70	        {data.usedInRiskScore ? "" : " · reported only, not part of the risk score"}
71	        {hasGaps && (
72	          <>
73	            {" · "}
74	            <span className="mr-1 inline-block h-2 w-2.5 rounded-sm align-middle" style={{ background: NO_DATA_FILL }} aria-hidden="true" />
