76	/**
77	 * Runs one model attempt and streams the answer text.
78	 * @param messages - history plus this turn's messages so far.
79	 * @param system - the system prompt.
80	 * @param deps - model and context.
81	 * @param tools - the tools for this request.
82	 * @param callbacks - progress hooks.
83	 * @param deadline - aborts when the whole turn runs out of time.
84	 * @returns the raw structured answer (or the reason it's missing) and the response messages.
85	 */
86	async function attempt(
87	  messages: ModelMessage[],
88	  system: string,
89	  deps: AgentDeps,
90	  tools: ReturnType<typeof buildTools>,
91	  callbacks: AgentCallbacks,
92	  deadline: AbortSignal,
93	): Promise<{ raw: LlmAnswer | null; problem: string | null; responseMessages: ModelMessage[]; usage: AgentResult["usage"] }> {
94	  let streamError: unknown = null;
95	  const result = streamText({
96	    model: deps.model,
97	    system,
98	    messages,
99	    tools,
100	    output: Output.object({ schema: llmAnswerSchema }),
101	    stopWhen: isStepCount(AGENT_LIMITS.maxToolSteps + 1),
102	    timeout: { totalMs: AGENT_TIMEOUTS.attemptMs, stepMs: AGENT_TIMEOUTS.stepMs, toolMs: AGENT_TIMEOUTS.toolMs },
103	    abortSignal: deadline,
104	    maxOutputTokens: AGENT_LIMITS.maxOutputTokens,
105	    maxRetries: 1,
106	    onError: ({ error }) => {
107	      streamError = error;
108	    },
109	  });
110	
111	  /**
112	   * Wraps a failed model call (timeout, network, provider error) in the 🦉 boundary format.
113	   * A step timeout makes the partial-output stream itself throw (D108), so the loop below is guarded too.
114	   */
115	  const callFailed = (cause: unknown) =>
116	    new BoundaryError({
117	      name: "LlmCallError",
118	      message: `The model call failed: ${describeUnknownError(cause)}`,
119	      functionName: "runAgent",
120	      boundary: "llm",
121	      cause,
122	    });
123	
124	  // The SDK restarts its partial output at every new step and stream retry, so the text can start
125	  // over. When it no longer continues what was sent, tell the caller and send it from the start.
126	  let sent = "";
127	  try {
128	    for await (const partial of result.partialOutputStream) {
129	      const text = (partial as Partial<LlmAnswer> | undefined)?.answer;
130	      if (typeof text !== "string") continue;
131	      if (!text.startsWith(sent)) {
132	        callbacks.onAnswerRestart?.();
133	        sent = "";
134	      }
135	      if (text.length > sent.length) {
136	        callbacks.onAnswerDelta?.(text.slice(sent.length));
137	        sent = text;
138	      }
139	    }
140	  } catch (error) {
141	    throw callFailed(streamError ?? error);
142	  }
143	
144	  let raw: LlmAnswer | null = null;
145	  let problem: string | null = null;
146	  try {
147	    raw = await result.output;
148	  } catch (error) {
149	    if (streamError) throw callFailed(streamError);
150	    if (NoObjectGeneratedError.isInstance(error) || NoOutputGeneratedError.isInstance(error)) {
151	      problem = `Your final answer did not match the required JSON schema (${describeUnknownError(error)}).`;
152	    } else throw callFailed(error);
153	  }
154	  const usage = await result.totalUsage;
155	  return {
156	    raw,
157	    problem,
158	    responseMessages: (await result.responseMessages) as ModelMessage[],
159	    usage: { inputTokens: usage.inputTokens ?? 0, outputTokens: usage.outputTokens ?? 0 },
160	  };
161	}
162	
163	/**
164	 * Answers one question.
165	 * @param request - the message and history.
166	 * @param deps - model and per-request context.
167	 * @param callbacks - progress hooks.
168	 * @returns the checked answer, the new history messages and token usage.
169	 * @throws AgentInputError for an invalid question; BoundaryError (llm) when the model fails or keeps producing invalid answers.
170	 */
171	export async function runAgent(request: AgentRequest, deps: AgentDeps, callbacks: AgentCallbacks = {}): Promise<AgentResult> {
172	  const message = request.message.trim();
173	  if (message.length === 0) throw new AgentInputError("Please type a question first — for example: “Why is the Dallas hub risky?”");
174	  if (message.length > AGENT_LIMITS.maxUserMessageChars) {
175	    throw new AgentInputError(`That message is too long for me — please keep it under ${AGENT_LIMITS.maxUserMessageChars.toLocaleString("en-US")} characters.`);
176	  }
177	
178	  const ledger = new ToolLedger();
179	  ledger.seedFromHistory(request.history);
180	  // Facts the system prompt states, so they're known even though no tool returned them: the hub count
181	  // ("36 hubs") and this year and last year ("Today is …"), which rule 14 asks the agent to name (D122).
182	  const year = Number(deps.context.today.slice(0, 4));
183	  ledger.addKnownNumbers([deps.context.hubs.length, year, year - 1]);
184	  const tools = buildTools(deps.context, { ledger, callbacks });
185	  const system = buildSystemPrompt(deps.context);
186	  const newMessages: ModelMessage[] = [{ role: "user", content: message }];
187	  const deadline = AbortSignal.timeout(AGENT_TIMEOUTS.turnMs); // one budget for both attempts
188	  const usage = { inputTokens: 0, outputTokens: 0 };
189	  let problems: string[] = [];
190	
191	  for (let attemptNo = 0; attemptNo <= AGENT_LIMITS.validationRetries; attemptNo++) {
192	    const run = await attempt([...request.history, ...newMessages], system, deps, tools, callbacks, deadline);
193	    newMessages.push(...run.responseMessages);
194	    usage.inputTokens += run.usage.inputTokens;
195	    usage.outputTokens += run.usage.outputTokens;
196	
197	    if (run.raw) {
198	      const final = finalizeAnswer(run.raw, {
199	        ledger,
200	        levelsByHub: deps.context.levelsByHub,
201	        model: deps.modelId,
202	        retried: attemptNo > 0,
203	      });
204	      if (final.ok) return { answer: final.answer, newMessages, usage };
205	      problems = final.problems;
206	    } else {
207	      problems = [run.problem ?? "No answer was produced."];
208	    }
209	
210	    if (attemptNo < AGENT_LIMITS.validationRetries) {
211	      callbacks.onRetry?.(problems);
212	      newMessages.push({
213	        role: "user",
214	        content: `${RETRY_FEEDBACK_PREFIX}\n- ${problems.join("\n- ")}\nFix these and answer again. Use the tool results you already have; only call a tool if you truly need data you don't have yet.`,
215	      });
216	    }
217	  }
218	
219	  throw new BoundaryError({
220	    name: "AgentAnswerValidationError",
221	    message: `The answer failed validation ${AGENT_LIMITS.validationRetries + 1} times: ${problems.join(" | ")}`,
222	    functionName: "runAgent",
223	    boundary: "llm",
224	  });
225	}
