1	/**
2	 * @module core/db/chatRepository
3	 *
4	 * Server-side conversation memory (D25, G7): sessions and their messages,
5	 * including tool calls and results, so follow-ups reuse exact numbers.
6	 */
7	import { modelMessageSchema, type ModelMessage } from "ai";
8	import { z } from "zod";
9	import type { FinalAnswer } from "../agent/answerSchema";
10	import { RETRY_FEEDBACK_PREFIX } from "../agent/config";
11	import { BoundaryError } from "../errors/boundaryError";
12	import type { Json } from "./database.types";
13	import { getDb, type Db } from "./client";
14	
15	/** Shorthand for a database failure in this module. */
16	function dbError(functionName: string, what: string, error: { message: string }): BoundaryError {
17	  return new BoundaryError({
18	    name: "SupabaseQueryError",
19	    message: `${what}: ${error.message}`,
20	    functionName,
21	    boundary: "database",
22	    cause: error,
23	  });
24	}
25	
26	/**
27	 * Returns an existing session id, or creates a new session.
28	 * @param sessionId - id from the browser, if any.
29	 * @param db - database client (injectable).
30	 * @returns the session id to use.
31	 * @throws BoundaryError (database) on failure.
32	 */
33	export async function ensureSession(sessionId: string | null, db: Db = getDb()): Promise<string> {
34	  if (sessionId && z.uuid().safeParse(sessionId).success) {
35	    const { data, error } = await db.from("chat_sessions").select("id").eq("id", sessionId).maybeSingle();
36	    if (error) throw dbError("ensureSession", "Could not read the chat session", error);
37	    if (data) return data.id;
38	  }
39	  const { data, error } = await db.from("chat_sessions").insert({}).select("id").single();
40	  if (error) throw dbError("ensureSession", "Could not create a chat session", error);
41	  return data.id;
42	}
43	
44	/**
45	 * Loads the last `turns` turns of a conversation as model messages (oldest first).
46	 * A turn starts at a user message that the user wrote: the validation-retry feedback is stored
47	 * with the user role too (the model must see it as such), but it doesn't start a turn.
48	 * @param sessionId - session id.
49	 * @param turns - how many recent turns to include.
50	 * @param db - database client (injectable).
51	 * @returns the messages, validated with the AI SDK's message schema.
52	 * @throws BoundaryError (database) when a query fails or a stored message is malformed.
53	 */
54	export async function loadHistory(sessionId: string, turns: number, db: Db = getDb()): Promise<ModelMessage[]> {
55	  // At most one feedback message per turn, so twice as many user rows always hold `turns` real ones.
56	  const userRows = await db
57	    .from("chat_messages")
58	    .select("created_at, content")
59	    .eq("session_id", sessionId)
60	    .eq("role", "user")
61	    .order("created_at", { ascending: false })
62	    .limit(turns * 2);
63	  if (userRows.error) throw dbError("loadHistory", "Could not read chat history", userRows.error);
64	  const starts = userRows.data.filter((row) => !isRetryFeedback(row.content)).slice(0, turns);
65	  if (starts.length === 0) return [];
66	  const from = starts[starts.length - 1].created_at;
67	
68	  const { data, error } = await db
69	    .from("chat_messages")
70	    .select("content")
71	    .eq("session_id", sessionId)
72	    .gte("created_at", from)
73	    .order("created_at", { ascending: true });
74	  if (error) throw dbError("loadHistory", "Could not read chat history", error);
75	  const parsed = z.array(modelMessageSchema).safeParse(data.map((row) => row.content));
76	  if (!parsed.success) {
77	    throw new BoundaryError({
78	      name: "ChatHistoryValidationError",
79	      message: `Stored messages of session ${sessionId} are malformed`,
80	      functionName: "loadHistory",
81	      boundary: "database",
82	      cause: parsed.error,
83	    });
84	  }
85	  return parsed.data;
86	}
87	
88	/**
89	 * Whether a stored user message is the validation-retry feedback rather than a question.
90	 * @param content - the stored message (a ModelMessage as JSON).
91	 * @returns true for retry feedback.
92	 */
93	export function isRetryFeedback(content: Json): boolean {
94	  const text = (content as { content?: unknown } | null)?.content;
95	  return typeof text === "string" && text.startsWith(RETRY_FEEDBACK_PREFIX);
96	}
97	
98	/**
99	 * Saves one turn. Rows get strictly increasing timestamps (1 ms apart) so their
100	 * order is unambiguous — a batch insert would otherwise give them all the same `now()`.
101	 * @param sessionId - session id.
102	 * @param messages - the turn's messages (user, assistant, tool …).
103	 * @param answer - the final checked answer (stored on the last assistant message).
104	 * @param model - model id.
105	 * @param db - database client (injectable).
106	 * @throws BoundaryError (database) on failure.
107	 */
108	export async function saveTurn(
109	  sessionId: string,
110	  messages: ModelMessage[],
111	  answer: FinalAnswer,
112	  model: string,
113	  db: Db = getDb(),
114	): Promise<void> {
115	  const base = Date.now();
116	  const kept = messages.filter((m) => m.role !== "system");
117	  const lastAssistant = kept.map((m) => m.role).lastIndexOf("assistant"); // index into the saved rows
118	  const rows = kept
119	    .map((message, index) => ({
120	      session_id: sessionId,
121	      role: message.role,
122	      content: message as unknown as Json,
123	      answer: index === lastAssistant ? (answer as unknown as Json) : null,
124	      model: message.role === "assistant" ? model : null,
125	      created_at: new Date(base + index).toISOString(),
126	    }));
127	  const { error } = await db.from("chat_messages").insert(rows);
128	  if (error) throw dbError("saveTurn", "Could not save the conversation", error);
129	
130	  const firstUser = messages.find((m) => m.role === "user");
131	  const title = typeof firstUser?.content === "string" ? firstUser.content.slice(0, 80) : null;
132	  const session = await db
133	    .from("chat_sessions")
134	    .update({ last_message_at: new Date(base + rows.length).toISOString() })
135	    .eq("id", sessionId);
136	  if (session.error) throw dbError("saveTurn", "Could not update the chat session", session.error);
137	  if (title) await db.from("chat_sessions").update({ title }).eq("id", sessionId).is("title", null);
138	}
